ction(response) {\\r\\n                console.log(response)\\r\\n                \\/\\/ Redirect or show a success message\\r\\n                \\/\\/ window.location.href = \'http:\\/\\/localhost\\/tpmshaadi\\/thank-you\';\\r\\n            },\\r\\n            error: function() {\\r\\n                console.error(\'Form submission failed\');\\r\\n            }\\r\\n        });\\r\\n    });\\r\\n});\\r\\n\\r\\n<\\/script>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<script>\\r\\n\\r\\n{\\/* document.addEventListener(\\\"DOMContentLoaded\\\", function() {\\r\\n    \\/\\/ Fetch the nonce via an AJAX request\\r\\n    fetch(\'http:\\/\\/localhost\\/tpmshaadi\\/wp-admin\\/admin-ajax.php?action=generate_nonce&nonce_action=your_custom_action_nonce\')\\r\\n        .then(response => response.text())\\r\\n        .then(nonce => {\\r\\n            document.getElementById(\'your_custom_action_nonce\').value = nonce;\\r\\n        });\\r\\n\\r\\n    \\/\\/ Set the form action dynamically\\r\\n    document.getElementById(\'customForm\').action = \'http:\\/\\/localhost\\/tpmshaadi\\/wp-admin\\/admin-post.php\';\\r\\n\\r\\n    document.getElementById(\'customForm\').addEventListener(\'submit\', function(event) {\\r\\n        event.preventDefault(); \\/\\/ Prevent the default form submission\\r\\n\\r\\n        const form = event.target;\\r\\n        const formData = new FormData(form);\\r\\n\\r\\n        console.log(formData);\\r\\n        console.log(form);\\r\\n\\r\\n        fetch(form.action, {\\r\\n            method: \'POST\',\\r\\n            body: formData\\r\\n        })\\r\\n        .then(response => {\\r\\n            if (response.ok) {\\r\\n                \\/\\/ Redirect or show a success message\\r\\n                window.location.href = \'http:\\/\\/localhost\\/tpmshaadi\\/thank-you\';\\r\\n            } else {\\r\\n                \\/\\/ Handle errors\\r\\n                con