\\n                <option value=\\\"malay\\\">Malay<\\/option>\\r\\n                <option value=\\\"malayalam\\\">Malayalam<\\/option>\\r\\n                <option value=\\\"manipuri\\\">Manipuri<\\/option>\\r\\n                <option value=\\\"marathi\\\">Marathi<\\/option>\\r\\n                <option value=\\\"marwari\\\">Marwari<\\/option>\\r\\n                <option value=\\\"miji\\\">Miji<\\/option>\\r\\n                <option value=\\\"mizo\\\">Mizo<\\/option>\\r\\n                <option value=\\\"monpa\\\">Monpa<\\/option>\\r\\n                <option value=\\\"nepali\\\">Nepali<\\/option>\\r\\n                <option value=\\\"odia\\\">Odia<\\/option>\\r\\n                <option value=\\\"pashto\\\">Pashto<\\/option>\\r\\n                <option value=\\\"persian\\\">Persian<\\/option>\\r\\n                <option value=\\\"punjabi\\\">Punjabi<\\/option>\\r\\n                <option value=\\\"rajashtani\\\">Rajashtani<\\/option>\\r\\n                <option value=\\\"russian\\\">Russian<\\/option>\\r\\n                <option value=\\\"sanskrit\\\">Sanskrit<\\/option>\\r\\n                <option value=\\\"santhali\\\">Santhali<\\/option>\\r\\n                <option value=\\\"seraiki\\\">Seraiki<\\/option>\\r\\n                <option value=\\\"sindhu\\\">Sindhu<\\/option>\\r\\n                <option value=\\\"sinhala\\\">Sinhala<\\/option>\\r\\n                <option value=\\\"sourashtra\\\">Sourashtra<\\/option>\\r\\n                <option value=\\\"spanish\\\">Spanish<\\/option>\\r\\n                <option value=\\\"swedish\\\">Swedish<\\/option>\\r\\n                <option value=\\\"tagalog\\\">Tagalog<\\/option>\\r\\n                <option value=\\\"tamil\\\">Tamil<\\/option>\\r\\n                <option value=\\\"telegu\\\">Telegu<\\/option>\\r\\n                <option value=\\\"tulu\\\">Tulu<\\/option>\\r\\n                <option value=\\\"urdu\\\">Urdu<\\/option>\\r\\n                <option value=\\\"other\\\">Other<\\/option>\\r\\n            <\\/optgroup>\\r\\n        <\\/select>\\r\\n    <\\/div>\\r\\n\\r\\n\\r\\n<\\/div>\\r\\n\\r\\n\\r\\n\\r\\n<div class=\\\"row-c gender\\\">\\r\\n    <label for=\\\"gender\\\">Select<\\/label>\\r\\n    <div class=\\\"contt\\\">\\r\\n        <label class=\\\"gender-radio \\\">\\r\\n            <input required type=\\\"radio\\\" name=\\\"gender\\\" value=\\\"girl\\\"> I\'m girl\\r\\n          <\\/label>\\r\\n          <label class=\\\"gender-radio\\\">\\r\\n            <input required type=\\\"radio\\\" name=\\\"gender\\\" value=\\\"boy\\\"> I\'m boy\\r\\n          <\\/label>\\r\\n    <\\/div>\\r\\n<\\/div>\\r\\n\\r\\n\\r\\n<div class=\\\"fieldgroup\\\">\\r\\n    <label for=\\\"email\\\">Email<\\/label>\\r\\n    <input required name=\\\"email\\\" type=\\\"email\\\" placeholder=\\\"Enter your email\\\">\\r\\n<\\/div>\\r\\n\\r\\n<div class=\\\"fieldgroup\\\">\\r\\n    <span class=\\\"errors\\\">\\r\\n         \\r\\n    <\\/span>\\r\\n<\\/div>\\r\\n\\r\\n\\r\\n    \\r\\n    <div class=\\\"cont-flex\\\">\\r\\n    <button class=\\\"submit-btn\\\" type=\\\"submit\\\">Submit<\\/button>\\r\\n    <\\/div>\\r\\n<\\/form>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<script>\\r\\n    document.addEventListener(\'DOMContentLoaded\', function() {\\r\\n        const genderLabels = document.querySelectorAll(\'#regform1 .gender .contt label\');\\r\\n\\r\\n        genderLabels.forEach(label => {\\r\\n            label.addEventListener(\'click\', function() {\\r\\n                \\/\\/ Remove \'active\' class from all labels\\r\\n                genderLabels.forEach(l => l.classList.remove(\'active\'));\\r\\n                \\r\\n                \\/\\/ Add \'active\' class to the clicked label\\r\\n                this.classList.add(\'active\');\\r\\n            });\\r\\n        });\\r\\n    });\\r\\n    \\r\\n    \\r\\n    \\r\\n    \\r\\n    \\r\\n<\\/script>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<script>\\r\\n    jQuery(document).ready(function($) {\\r\\n        \\/\\/ Fetch the nonce via an AJAX request\\r\\n        $.ajax({\\r\\n            url: \'http:\\/\\/localhost\\/tpmshaadi\\/wp-admin\\/admin-ajax.php\',\\r\\n            method: \'GET\',\\r\\n            data: {\\r\\n                action: \'generate_nonce\',\\r\\n                nonce_action: \'regsiter1_action_nonce\'\\r\\n            },\\r\\n            success: function(nonce) {\\r\\n                $(\'#regsiter1_action_nonce\').val(nonce);\\r\\n            },\\r\\n            error: function() {\\r\\n                console.error(\'Failed to fetch nonce\');\\r\\n            }\\r\\n        });\\r\\n    \\r\\n        \\/\\/ Set the form action dynamically\\r\\n        $(\'#customForm\').attr(\'action\', \'http:\\/\\/localhost\\/tpmshaadi\\/wp-admin\\/admin-post.php\');\\r\\n    \\r\\n        $(\'#customForm\').submit(function(event) {\\r\\n            event.preventDefault(); \\/\\/ Prevent the default form submission\\r\\n    \\r\\n            var form = $(this);\\r\\n            var formData = new FormData(form[0]);\\r\\n    \\r\\n            console.log(formData);\\r\\n            console.log(form);\\r\\n    \\r\\n            $.ajax({\\r\\n                url: form.attr(\'action\'),\\r\\n                method: \'POST\',\\r\\n                data: formData,\\r\\n                contentType: false,\\r\\n                processData: false,\\r\\n                success: function(response) {\\r\\n                    console.log(response)\\r\\n                    \\/\\/ Redirect or show a success message\\r\\n                    \\/\\/ window.location.href = \'http:\\/\\/localhost\\/tpmshaadi\\/thank-you\';\\r\\n                },\\r\\n                error: function() {\\r\\n                    console.error(\'Form submission failed\');\\r\\n                     let errorSpan = document.querySelector(\'#regform1.errors\');\\r\\n\\r\\n                    errorSpan.textContent = error.message;\\r\\n                }\\r\\n            });\\r\\n        });\\r\\n    });\\r\\n    \\r\\n    <\\/scr