add(\'active\');\\r\\n            });\\r\\n        });\\r\\n    });\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<\\/script>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<script>\\r\\n    jQuery(document).ready(function ($) {\\r\\n        \\/\\/ Fetch the nonce via an AJAX request\\r\\n        $.ajax({\\r\\n            url: \'http:\\/\\/localhost\\/tpmshaadi\\/wp-admin\\/admin-ajax.php\',\\r\\n            method: \'GET\',\\r\\n            data: {\\r\\n                action: \'generate_nonce\',\\r\\n                nonce_action: \'regsiter1_action_nonce\'\\r\\n            },\\r\\n            success: function (nonce) {\\r\\n                $(\'#regsiter1_action_nonce\').val(nonce);\\r\\n            },\\r\\n            error: function () {\\r\\n                console.error(\'Failed to fetch nonce\');\\r\\n            }\\r\\n        });\\r\\n\\r\\n        \\/\\/ Set the form action dynamically\\r\\n        $(\'#customForm\').attr(\'action\', \'http:\\/\\/localhost\\/tpmshaadi\\/wp-admin\\/admin-post.php\');\\r\\n\\r\\n        $(\'#customForm\').submit(function (event) {\\r\\n            event.preventDefault(); \\/\\/ Prevent the default form submission\\r\\n\\r\\n            var form = $(this);\\r\\n            var formData = new FormData(form[0]);\\r\\n\\r\\n            console.log(formData);\\r\\n            console.log(form);\\r\\n\\r\\n            $.ajax({\\r\\n                url: form.attr(\'action\'),\\r\\n                method: \'POST\',\\r\\n                data: formData,\\r\\n                contentType: false,\\r\\n                processData: false,\\r\\n                success: function (response) {\\r\\n                    console.log(response)\\r\\n                    \\/\\/ Redirect or show a success message\\r\\n                    \\/\\/ window.location.href = \'http:\\/\\/localhost\\/tpmshaadi\\/thank-you\';\\r\\n                },\\r\\n                error: function (jqXHR, textStatus, errorThrown) {\\r\\n                    console.error(\\\"Error Status: \\\" + textSt