add(\'active\');\\r\\n            });\\r\\n        });\\r\\n    });\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<\\/script>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<script>\\r\\n    jQuery(document).ready(function ($) {\\r\\n        \\/\\/ Fetch the nonce via an AJAX request\\r\\n        $.ajax({\\r\\n            url: \'http:\\/\\/localhost\\/tpmshaadi\\/wp-admin\\/admin-ajax.php\',\\r\\n            method: \'GET\',\\r\\n            data: {\\r\\n                action: \'generate_nonce\',\\r\\n                nonce_action: \'regsiter1_action_nonce\'\\r\\n            },\\r\\n            success: function (nonce) {\\r\\n                $(\'#regsiter1_action_nonce\').val(nonce);\\r\\n            },\\r\\n            error: function () {\\r\\n                console.error(\'Failed to fetch nonce\');\\r\\n            }\\r\\n        });\\r\\n\\r\\n        \\/\\/ Set the form action dynamically\\r\\n        $(\'#customForm\').attr(\'action\', \'http:\\/\\/localhost\\/tpmshaadi\\/wp-admin\\/admin-post.php\');\\r\\n\\r\\n        $(\'#customForm\').submit(function (event) {\\r\\n            event.preventDefault(); \\/\\/ Prevent the default form submission\\r\\n\\r\\n            var form = $(this);\\r\\n            var formData = new FormData(form[0]);\\r\\n\\r\\n            console.log(formData);\\r\\n            console.log(form);\\r\\n\\r\\n            $.ajax({\\r\\n                url: form.attr(\'action\'),\\r\\n                method: \'POST\',\\r\\n                data: formData,\\r\\n                contentType: false,\\r\\n                processData: false,\\r\\n                success: function (response) {\\r\\n                    console.log(response)\\r\\n                    \\/\\/ Redirect or show a success message\\r\\n                    \\/\\/ window.location.href = \'http:\\/\\/localhost\\/tpmshaadi\\/thank-you\';\\r\\n                },\\r\\n                error: function (jqXHR, textStatus, errorThrown) {\\r\\n                    console.error(\\\"Error Status: \\\" + textStatus);\\r\\n                    console.error(\\\"Error Thrown: \\\" + errorThrown);\\r\\n                    \\/\\/ console.error(\\\"Response Text: \\\" + jqXHR.responseText);\\r\\n                }\\r\\n            });\\r\\n        });\\r\\n    });\\r\\n\\r\\n<\\/script>\",\"_element_id\":\"regform1\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"2ca19ce\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"17d6835\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"space\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]}},\"elements\":[],\"widgetType\":\"spacer\"}],\"isInner\":false},{\"id\":\"61975d2\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"},\"background_background\":\"classic\",\"padding\":{\"unit\":\"rem\",\"top\":\"02\",\"right\":\"0\",\"bottom\":\"02\",\"left\":\"0\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"rem\",\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"isLinked\":true},\"padding_mobile\":{\"unit\":\"rem\",\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"isLinked\":true},\"__globals__\":{\"background_color\":\"globals\\/colors?id=c878fba\"}},\"elements\":[{\"id\":\"d79d677\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"{1762a5fadd4ffd2cadcf60985214aac38227c42d0a1f0b643f946400dadc3b59}\",\"size\":\"50\"},\"padding\":{\"unit\":\"rem\",\"top\":\"1\",\"right\":\"01\",\"bottom\":\"1\",\"left\":\"01\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"rem\",\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"isLinked\":true},\"padding_mobile\":{\"unit\":\"rem\",\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"isLinked\":true}},\"elements\":[{\"id\":\"bd619e4\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/localhost\\/tpm