 Handle error response\\r\\n                console.log(error.responseText); \\/\\/ Example: Log error message\\r\\n            }\\r\\n        });\\r\\n    });\\r\\n});\\r\\n\\r\\n    \\r\\n    <\\/script>\\r\\n    \\r\\n    \\r\\n    \\r\\n    \\r\\n    \\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\",\"_element_id\":\"regform1\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"2ca19ce\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"17d6835\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"space\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]}},\"elements\":[],\"widgetType\":\"spacer\"}],\"isInner\":false},{\"id\":\"61975d2\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"},\"background_background\":\"classic\",\"padding\":{\"unit\":\"rem\",\"top\":\"02\",\"right\":\"0\",\"bottom\":\"02\",\"left\":\"0\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"rem\",\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"isLinked\":true},\"padding_mobile\":{\"unit\":\"rem\",\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"isLinked\":true},\"__globals__\":{\"background_color\":\"globals\\/colors?id=c878fba\"}},\"elements\":[{\"id\":\"d79d677\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"{1762a5fadd4ffd2cadcf60985214aac38227c42d0a1f0b643f946400dadc3b59}\",\"size\":\"50\"},\"padding\":{\"unit\":\"rem\",\"top\":\"1\",\"right\":\"01\",\"bottom\":\"1\",\"left\":\"01\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"rem\",\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"isLinked\":true},\"padding_mobile\":{\"unit\":\"rem\",\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"lef