INSERT INTO wp_posts VALUES("9", "1", "2024-07-09 20:13:31", "2024-07-09 14:43:31", "<style>/*! elementor - v3.23.0 - 23-07-2024 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>Register</h2>		\n<style>\n    #regform1 label {\n        font-size: 0.9rem;\n        color: #7A7A7A;\n        font-weight: 300;\n    }\n    #regform1 input, select {\n        outline: 0px;\n        border: 0;\n        border-bottom: 2px solid #9C27B0;\n        border-radius: 0px;\n        padding-left: 0.4rem;\n        color: #9C27B0;\n    }\n    #regform1 .fieldgroup {\n        margin-bottom: 1.6rem;\n    }\n    #regform1 .row-c {\n        display: flex;\n        gap: 1rem;\n        align-items: center;\n        justify-content: space-between;\n    }\n    #regform1 .row-c .fieldgroup {\n        width: 50{1762a5fadd4ffd2cadcf60985214aac38227c42d0a1f0b643f946400dadc3b59};\n    }\n    #regform1 optgroup {\n        font-weight: 300;\n        font-size: 0.9rem;\n        color: #646464;\n    }\n    #regform1 option {\n        color: #9C27B0;\n    }\n    #regform1 .gender {\n        display: flex;\n        justify-content: center;\n        /*border: 1px solid black;*/\n    }\n    #regform1 .gender .contt {\n        display: flex;\n        gap: .8rem;\n    }\n    #regform1 .gender .contt label {\n        background-color: transparent;\n        border: 2px solid #9C27B0;\n        padding: 6px 16px;\n        border-radius: 22px;\n        color: #9C27B0;\n        font-size: 1rem;\n        font-weight: 500;\n    }\n    #regform1 .gender .contt label:hover,\n    #regform1 .gender .contt label:active {\n        color: white;\n        background-color: #9C27B0;\n    }\n        #regform1 .gender .contt label.active {\n        color: white;\n        background-color: #9C27B0;\n    }\n     #regform1 .gender .contt label input[type=\'radio\']{\n         display: none;\n     }\n     #regform1 .cont-flex  {\n         text-align: center;\n     }\n     #regform1 .cont-flex button {\n        border: none;\n        border-bottom: 2px solid white;\n        padding: 0 6px;\n        font-weight: 500;\n        color: #9C27B0;\n        background: none;\n     }\n      #regform1 .cont-flex button:hover {\n        border-bottom: 2px solid #9C27B0;\n      }\n      #regform1 .errors {\n        font-weight: 400;\n        font-size: 0.9rem;\n        color: red;\n      }\n</style>\n<form id=\"tpm-shaadi-form\" method=\"POST\">\n        <label for=\"profile-for\">Create profile for</label>\n        <select name=\"profile-for\" id=\"profile-for\">\n            <option value=\"self\">Self</option>\n            <option value=\"son\">Son</option>\n            <option value=\"brother\">Brother</option>\n            <option value=\"sister\">Sister</option>\n            <option value=\"daughter\">Daughter</option>\n            <option value=\"friend\">Friend</option>\n            <option value=\"relative\">Relative</option>\n        </select>\n        <label for=\"dob\">Date of birth</label>\n        <input name=\"dob\" id=\"dob\" required type=\"date\">\n        <label for=\"languages\">Select language</label>\n        <select name=\"languages\" id=\"languages\">\n            <optgroup label=\"Frequently used\">\n                <option value=\"hindi\">Hindi</option>\n                <option value=\"marathi\">Marathi</option>\n                <option value=\"punjabi\">Punjabi</option>\n                <option value=\"bengali\">Bengali</option>\n                <option value=\"gujarati\">Gujarati</option>\n                <option value=\"urdu\">Urdu</option>\n                <option value=\"telegu\">Telegu</option>\n                <option value=\"kannada\">Kannada</option>\n                <option value=\"english\">English</option>\n                <option value=\"tamil\">Tamil</option>\n                <option value=\"oriya\">Oriya</option>\n                <option value=\"marwari\">Marwari</option>\n            </optgroup>\n            <optgroup label=\"More\">\n                <option value=\"aka\">Aka</option>\n                <option value=\"arabic\">Arabic</option>\n                <option value=\"arunachali\">Arunachali</option>\n                <option value=\"assamese\">Assamese</option>\n                <option value=\"awadhi\">Awadhi</option>\n                <option value=\"baluchi\">Baluchi</option>\n                <option value=\"bengali\">Bengali</option>\n                <option value=\"bhojpuri\">Bhojpuri</option>\n                <option value=\"brahui\">Brahui</option>\n                <option value=\"brij\">Brij</option>\n                <option value=\"burmese\">Burmese</option>\n                <option value=\"chattisgarhi\">Chattisgarhi</option>\n                <option value=\"chinese\">Chinese</option>\n                <option value=\"coorgi\">Coorgi</option>\n                <option value=\"dogri\">Dogri</option>\n                <option value=\"english\">English</option>\n                <option value=\"french\">French</option>\n                <option value=\"garhwali\">Garhwali</option>\n                <option value=\"garo\">Garo</option>\n                <option value=\"gujarati\">Gujarati</option>\n                <option value=\"havyanavi\">Havyanavi</option>\n                <option value=\"himachali/pahari\">Himachali/Pahari</option>\n                <option value=\"hindi\">Hindi</option>\n                <option value=\"hinko\">Hinko</option>\n                <option value=\"kakbarak\">Kakbarak</option>\n                <option value=\"kanauji\">Kanauji</option>\n                <option value=\"kannada\">Kannada</option>\n                <option value=\"kashmiri\">Kashmiri</option>\n                <option value=\"khandesi\">Khandesi</option>\n                <option value=\"khusi\">Khusi</option>\n                <option value=\"konkani\">Konkani</option>\n                <option value=\"koshali\">Koshali</option>\n                <option value=\"kumaoni\">Kumaoni</option>\n                <option value=\"kutchi\">Kutchi</option>\n                <option value=\"ladakhi\">Ladakhi</option>\n                <option value=\"lepcha\">Lepcha</option>\n                <option value=\"magahi\">Magahi</option>\n                <option value=\"maithili\">Maithili</option>\n                <option value=\"malay\">Malay</option>\n                <option value=\"malayalam\">Malayalam</option>\n                <option value=\"manipuri\">Manipuri</option>\n                <option value=\"marathi\">Marathi</option>\n                <option value=\"marwari\">Marwari</option>\n                <option value=\"miji\">Miji</option>\n                <option value=\"mizo\">Mizo</option>\n                <option value=\"monpa\">Monpa</option>\n                <option value=\"nepali\">Nepali</option>\n                <option value=\"odia\">Odia</option>\n                <option value=\"pashto\">Pashto</option>\n                <option value=\"persian\">Persian</option>\n                <option value=\"punjabi\">Punjabi</option>\n                <option value=\"rajashtani\">Rajashtani</option>\n                <option value=\"russian\">Russian</option>\n                <option value=\"sanskrit\">Sanskrit</option>\n                <option value=\"santhali\">Santhali</option>\n                <option value=\"seraiki\">Seraiki</option>\n                <option value=\"sindhu\">Sindhu</option>\n                <option value=\"sinhala\">Sinhala</option>\n                <option value=\"sourashtra\">Sourashtra</option>\n                <option value=\"spanish\">Spanish</option>\n                <option value=\"swedish\">Swedish</option>\n                <option value=\"tagalog\">Tagalog</option>\n                <option value=\"tamil\">Tamil</option>\n                <option value=\"telegu\">Telegu</option>\n                <option value=\"tulu\">Tulu</option>\n                <option value=\"urdu\">Urdu</option>\n                <option value=\"other\">Other</option>\n            </optgroup>\n        </select>\n    <label for=\"gender\">Select</label>\n        <label>\n            <input  type=\"radio\" name=\"gender\" value=\"girl\"> I\'m girl\n          </label>\n          <label>\n            <input  type=\"radio\" name=\"gender\" value=\"boy\"> I\'m boy\n          </label>\n    <label for=\"email\">Email</label>\n    <input required name=\"email\" type=\"email\" placeholder=\"Enter your email\">\n    <button type=\"submit\">Submit</button>\n</form>\n			<style>.elementor-widget-image-box .elementor-image-box-content{width:100{1762a5fadd4ffd2cadcf60985214aac38227c42d0a1f0b643f946400dadc3b59}}@media (min-width:461px){.elementor-widget-image-box.elementor-position-left .elementor-image-box-wrapper,.elementor-widget-image-box.elementor-position-right .elementor-image-box-wrapper{display:flex}.elementor-widget-image-box.elementor-position-right .elementor-image-box-wrapper{text-align:end;flex-direction:row-reverse}.elementor-widget-image-box.elementor-position-left .elementor-image-box-wrapper{text-align:start;flex-direction:row}.elementor-widget-image-box.elementor-position-top .elementor-image-box-img{margin:auto}.elementor-widget-image-box.elementor-vertical-align-top .elementor-image-box-wrapper{align-items:flex-start}.elementor-widget-image-box.elementor-vertical-align-middle .elementor-image-box-wrapper{align-items:center}.elementor-widget-image-box.elementor-vertical-align-bottom .elementor-image-box-wrapper{align-items:flex-end}}@media (max-width:460px){.elementor-widget-image-box .elementor-image-box-img{margin-left:auto!important;margin-right:auto!important;margin-bottom:15px}}.elementor-widget-image-box .elementor-image-box-img{display:inline-block}.elementor-widget-image-box .elementor-image-box-title a{color:inherit}.elementor-widget-image-box .elementor-image-box-wrapper{text-align:center}.elementor-widget-image-box .elementor-image-box-description{margin:0}</style><figure><img width=\"100\" height=\"100\" src=\"http://localhost/tpmshaadi/wp-content/uploads/2024/07/icon-img.png\" alt=\"\" /></figure><h3>Register for free & put up your Profile</h3>		\n			<figure><img width=\"100\" height=\"100\" src=\"http://localhost/tpmshaadi/wp-content/uploads/2024/07/Group-25.png\" alt=\"\" /></figure><h3>Select & Connect with Matches you like</h3>		\n			<figure><img width=\"100\" height=\"100\" src=\"http://localhost/tpmshaadi/wp-content/uploads/2024/07/Group-24.png\" alt=\"\" /></figure><h3>Become a Premium Member & Start a Conversation</h3>", "home", "", "publish", "closed", "closed", "", "home", "", "", "2024-07-24 16:33:54", "2024-07-24 11:03:54", "", "0", "http://localhost/tpmshaadi/?page_id=9", "0", "page", "", "0");
